                goto not_found;

        e = strrchr(p, '-');
         if (!e || e == p)
                 goto not_found;

         r = parse_uid(e + 1, &uid);
         if (r < 0)
                 goto not_found;

        machine = strndupa(p, e - p);
        if (!machine_name_is_valid(machine))
                goto not_found;

