    DLOG(INFO) << "RegisterProperties" << (ibus_prop_list ? "" : " (clear)");

     ImePropertyList prop_list;  // our representation.
     if (ibus_prop_list) {
       if (!FlattenPropertyList(ibus_prop_list, &prop_list)) {
